import {Schema} from 'prosemirror-model';import {EditorState} from 'prosemirror-state';import {EditorView} from 'prosemirror-view';import {history,undo,redo} from 'prosemirror-history';import {keymap} from 'prosemirror-keymap';import {baseKeymap,toggleMark,setBlockType,wrapIn} from 'prosemirror-commands';import {wrapInList,splitListItem,liftListItem,sinkListItem} from 'prosemirror-schema-list';import {tableNodes,tableEditing,addRowAfter,addColumnAfter,deleteRow,deleteColumn,deleteTable} from 'prosemirror-tables';import {contentURL,canonicalNode} from '../../hub-cms/body.mjs';
